---GetCfDataByLine  从一行数据中获取对应列的数据
---@param lineData TableML.TableFileRow @ 行数据
---@param rowName string @ 列名
---@param type Constants.DataType @ 类型 1-int, 2-string
---@return string | number
function CfUtils.GetCfDataByLine(lineData, rowName, type)
    local cfData
    --local cfData = lineData:Get(rowName)
    if not type or type == Constants.DataType.String then
        cfData = parse_string(lineData, rowName)
    elseif type == Constants.DataType.Int then
        cfData = parse_number(lineData, rowName)
    elseif type == Constants.DataType.LocalString then
        cfData = ParseUtils.ParseLocalizeText(lineData, rowName)
    elseif type == Constants.DataType.PathName then
        cfData = ParseUtils.ParsePathName(lineData, rowName)
    end
    return cfData ~= nil and cfData or "无配置"
end

