--- 获取对照表的 表文件
---@param idSetting string @ 配置
---@param suffixName string | nil @ 自定义表名的后缀
---@return TableML.TableFile
function CfUtils.GetIdGroupTable(idSetting, suffixName)
    local tableName
    if not suffixName then
        tableName = string.format("%sIDGroup", idSetting)
    else
        tableName = string.format("%s" .. checkString(suffixName), idSetting)
    end

    local settingTableFile = SettingMgr:GetInstance():Get(idSetting)
    local idGroupTableFile = SettingMgr:GetInstance():Get(tableName)
    if idGroupTableFile.sourcePath == "" then
        idGroupTableFile.sourcePath = settingTableFile.sourcePath
    end
    return idGroupTableFile
end

