---GetIdGroupData  获取特殊修改后对照表的数据 数组
---@param idSetting string @ 配置
---@param key string
---@param rowName string @ 列名
---@param suffixName string | nil @ 自定义表名的后缀
---@return integer[]
function CfUtils.GetIdGroupData(idSetting, key, rowName, suffixName, splitFlag, disableSort)
    if isNull(disableSort) then
        disableSort = true
    end
    if not rowName then
        rowName = "id"
    end
    local idGroupTableFile = CfUtils.GetIdGroupTable(idSetting, suffixName)
    if not idGroupTableFile:HasPrimaryKey(checkString(key)) then
        return {}
    end

    ---@type TableML.TableFileRow
    local row = idGroupTableFile:GetByPrimaryKey(checkString(key))
    local ids = checkTable(parse_strings(row:Get(rowName), splitFlag or ','))

    if not disableSort then
        if Config and Config.DEBUG then
            printLog("WARNING", "非常耗时的方法(CfUtils.GetIdGroupData(%s, %s)),可以缓存结果,如果不需要排序,可以disableSort", idSetting, checkString(key))
        end
        --默认从小到大排序
        table.sort(ids, function(a, b)
            return checkNumber(a) < checkNumber(b)
        end)
    end
    return ids
end

