function CfUtils.GetTableValueKey(t, valueKey, value)
    if not t or not valueKey then
        return nil
    end
    for k, v in pairs(t) do
        if v[valueKey] == value then
            return k
        end
    end
    return nil
end

---Split  分割字符串
---@param str string
---@param reps string | nil @ default ;
---@return string[] | nil
function CfUtils.Split(str, reps)
    if not str then
        return nil
    end
    str = checkString(str)
    if not reps then
        reps = ";"
    end

    local resultStrList = {}
    string.gsub(str, '[^' .. reps .. ']+', function(w)
        table.insert(resultStrList, w)
    end)
    return resultStrList
end

---ShallowCopy  浅拷贝table
---@param orig table
---@return table
function CfUtils.ShallowCopy(orig)
    local copy
    if type(orig) == "table" then
        copy = {}
        for orig_key, orig_value in pairs(orig) do
            copy[orig_key] = orig_value
        end
    else
        -- number, string, boolean, etc
        copy = orig
    end
    return copy
end

