---AnglePos  俩点之间的角度
---@param from_ Vector3
---@param to_ Vector3
---@return number
function CfUtils.AnglePos(from_, to_)
    local x = from_.x - to_.x
    local y = from_.y - to_.y

    --斜边长度
    local hypotenuse = Mathf.Sqrt(Mathf.Pow(x, 2) + Mathf.Pow(y, 2))

    --求出弧度
    local cos = x / hypotenuse
    local radian = Mathf.Acos(cos)

    --用弧度算出角度    
    local angle = 180 / (Mathf.PI / radian)

    if y < 0 then
        angle = -angle
    elseif y == 0 and x < 0 then
        angle = 180
    end
    return angle
end

--俩点与x轴的夹角
---@param a Vector3
---@param b Vector3
---@return number
function CfUtils.AngleX(a, b)
    local dx = b.x - a.x
    local dy = b.y - a.y
    local dis = math.sqrt(dx * dx + dy * dy)
    local rota = dis > 0 and math.round(math.asin(dy / dis) / 3.14 * 180) or 0
    if b.x < a.x then
        rota = 180 - rota
    end
    return rota
end

--俩点与y轴的夹角
---@param a Vector3
---@param b Vector3
---@return number
function CfUtils.AngleY(a, b)
    local angle = CS.System.Math.Atan2((b.x - a.x), (b.y - a.y))
    return angle * (180 / 3.14)
end

--俩点与Z轴的夹角
---@param a Vector3
---@param b Vector3
---@return number
function CfUtils.AngleZ(a, b)
    local angle = CS.System.Math.Atan2((b.x - a.x), (b.z - a.z))
    return angle * (180 / 3.14)
end

---GetMazeMiniMapPoint 俩点间弧形运动
---@param go UnityEngine.Transform | UnityEngine.GameObject
---@param pos1 Vector3
---@param pos2 Vector3
---@param time number
---@param cbFun fun():void @ 结束回调
function CfUtils.ArcMove(go, pos1, pos2, time, cbFun, upFun)
    local tween = DOTween.To(function()
        return 0
    end,
            function(updateValue)
                --local pos = Vector3.Slerp(pos1, pos2, 2) + posCenter
                local posCenter = (pos1 + pos2) * 0.5
                posCenter = posCenter - Vector3(0, 1, 0)
                local riseRelCenter = pos1 - posCenter
                local setRelCenter = pos2 - posCenter

                go.transform.position = CS.UnityEngine.Vector3.Slerp(riseRelCenter, setRelCenter, updateValue)
                go.transform.position = go.transform.position + posCenter

                if upFun then
                    upFun()
                end
            end, 1, time)

    tween.onComplete = function()
        if cbFun then
            cbFun()
        end
    end
    --go.transform:DOMove(pos2, 2).onComplete = function() 
    --    return Vector3.Slerp(pos1, pos2, 2)
    --end
end

---@param time number
---@param updateFun fun(updateValue:number):void
---@param cbFun fun():void
---@param startFun fun():void
---@return DG.Tweening.Tweener
function CfUtils.DoTween(time, updateFun, cbFun, startFun)
    local tween = DOTween.To(function()
        return 0
    end,
            function(updateValue)
                if updateFun then
                    updateFun(updateValue)
                end
            end, 1, time)

    tween.onComplete = function()
        if cbFun then
            cbFun()
        end
    end

    tween.onPlay = function()
        if startFun then
            startFun()
        end
    end

    return tween
end

---ArcRotate 旋转tween
---@param go UnityEngine.Transform | UnityEngine.GameObject
---@param rot2 Quaternion
---@param time number
---@param cbFun fun():void
function CfUtils.ArcRotate(go, rot2, time, cbFun)
    local rot1 = go.transform.rotation
    local tween = DOTween.To(function()
        return 0
    end,
            function(updateValue)
                local rot = Quaternion.Slerp(rot1, rot2, updateValue)
                go.transform.rotation = rot
            end, 1, time)

    tween.onComplete = function()
        if cbFun then
            cbFun()
        end
    end
end

---RotateWithPoint 绕一个点Y轴旋转到目标点与其他点连线与轴的角度
---@param go UnityEngine.Transform | UnityEngine.GameObject
---@param centerPos Vector3
---@param angle integer
---@param axis Vector3
---@param time number @ 时间
---@param updateFun fun():void
---@param cbFun fun():void
function CfUtils.RotateWithPoint(go, centerPos, angle, axis, time, updateFun, cbFun)
    local beginPos = go.transform.position
    local beginRot = go.transform.rotation

    local tween = DOTween.To(function()
        return 0
    end,
            function(updateValue)
                local pos1, rot1 = CfUtils.MyRotateAround(beginPos, beginRot, centerPos, axis, updateValue)
                go.transform.position = pos1
                go.transform.rotation = rot1
                if updateFun then
                    updateFun()
                end
            end, angle, time)

    tween.onComplete = function()
        if cbFun then
            cbFun()
        end
    end
end

---TwoLineAngle  俩条线之间的夹角
---@param fromPos Vector3 @ 起始点
---@param centerPos Vector3 @ 中心点
---@param targetPos Vector3 @ 目标点
---@param normalPos Vector3 @ 法线向量
---@return integer
function CfUtils.TwoLineAngle(fromPos, centerPos, targetPos, normalPos)
    local fromVector = fromPos - centerPos
    local toVector = centerPos - targetPos

    local angle = CS.UnityEngine.Vector3.Angle(fromVector, toVector)
    local normal = CS.UnityEngine.Vector3.Cross(fromVector, toVector)  --叉乘求出法线向量
    angle = angle * CS.UnityEngine.Mathf.Sign(CS.UnityEngine.Vector3.Dot(normal, normalPos))  --求法线向量与物体上方向向量点乘，结果为1或-1，修正旋转方向 

    return angle
end

---MyRotateAround  绕某一点旋转 返回旋转角度之后的位置与角度
---@param mypos Vector3 @ 起始位置
---@param myrot Quaternion @ 起始rotation
---@param center Vector3 @ 绕的点
---@param axis Vector3 @ 旋转轴
---@param angle integer @ 旋转角度
---@return Vector3, Quaternion
function CfUtils.MyRotateAround(mypos, myrot, center, axis, angle)
    local returnPos
    local returnRot
    local rot = CS.UnityEngine.Quaternion.AngleAxis(angle, axis)
    local dir = mypos - center   --计算从圆心指向摄像头的朝向向量
    dir = rot * dir            --旋转此向量
    returnPos = center + dir --移动摄像机位置
    --go.transform.rotation = go.transform.rotation * CS.UnityEngine.Quaternion.Inverse(myrot) * rot *myrot  --设置角度另一种方法
    returnRot = rot * myrot --设置角度
    return returnPos, returnRot
end

---GetVectorAngle  俩个向量的夹角
---@param fromVector Vector3
---@param toVector Vector3
---@param normalVector Vector3 @ 法线
---@return integer
function CfUtils.GetVectorAngle(fromVector, toVector, normalVector)
    normalVector = normalVector or Vector3(0, 1, 0)
    local angle = CS.UnityEngine.Vector3.Angle(fromVector, toVector)
    local normal = CS.UnityEngine.Vector3.Cross(fromVector, toVector)
    angle = angle * CS.UnityEngine.Mathf.Sign(CS.UnityEngine.Vector3.Dot(normal, normalVector))
    return angle
end

---CalculateCubicBezierPoint 贝塞尔曲线点  二阶
---@param t number 插值
---@param p0 Vector3  起点
---@param p1 Vector3 中间点
---@param p2 Vector3 终点
---@return Vector3
function CfUtils.CalculateCubicBezierPoint(t, p0, p1, p2)
    local t1 = 1 - t
    local p0p1 = Vector3(p0.x * t1, p0.y * t1, p0.z * t1) + Vector3(p1.x * t, p1.y * t, p1.z * t)
    local p1p2 = Vector3(p1.x * t1, p1.y * t1, p1.z * t1) + Vector3(p2.x * t, p2.y * t, p2.z * t)
    local p = Vector3(p0p1.x * t1, p0p1.y * t1, p0p1.z * t1) + Vector3(p1p2.x * t, p1p2.y * t, p1p2.z * t)
    return p
end

---GetBeizerList 贝塞尔曲线点  二阶
---@param startPoint Vector3 @ 起点
---@param controlPoint Vector3 @ 中间点
---@param endPoint Vector3 @ 终点
---@param segmentNum integer @ 点的数量
---@return Vector3[]
function CfUtils.GetBeizerList(startPoint, controlPoint, endPoint, segmentNum)
    local path = {}
    for i = 1, segmentNum do
        local t = i / segmentNum
        local pixel = CfUtils.CalculateCubicBezierPoint(t, startPoint, controlPoint, endPoint)
        path[i] = pixel
    end
    return path
end

---UIWorldToScreenPos 点击ui的坐标转换
---@param uiNodeGo UnityEngine.Transform | UnityEngine.GameObject
---@param parGo UnityEngine.Transform | UnityEngine.GameObject @ 计算位置的父物体
---@param targetCam UnityEngine.Camera | nil
---@return Vector2
function CfUtils.UIWorldToScreenPos(uiNodeGo, parGo, targetCam)
    if not uiNodeGo then
        return
    end
    if not parGo then
        parGo = UIModule.RootCanvas
    end

    local uiCam = KTool.FindCameraForLayer(CS.UnityEngine.LayerMask.NameToLayer("UI"))
    if not targetCam then
        targetCam = uiCam
    end

    local topLayerRt = parGo.transform:GetComponent("RectTransform")
    local pos = CS.UnityEngine.RectTransformUtility.WorldToScreenPoint(targetCam, uiNodeGo.transform.position)
    local test
    test, pos = CS.UnityEngine.RectTransformUtility.ScreenPointToLocalPointInRectangle(topLayerRt, pos, uiCam)
    return pos
end

