---GetUITargetPos 点击ui的坐标转换
---@param targetNodeGo UnityEngine.GameObject @ 目标节点
---@param nodeGo UnityEngine.GameObject | nil @ 自身节点
---@param parGo UnityEngine.GameObject | nil @ default UIRootCanvas
---@param targetPivotX number | nil @ default 0.5
---@param targetPivotY number | nil @ default 0.5
---@param nodePivotX number | nil @ default 0.5
---@param nodePivotY number | nil @ default 0.5
---@param isOpposite boolean | nil @ 是否相反
---@return Vector3
function CfUtils.GetUITargetPos(targetNodeGo, nodeGo, parGo, targetPivotX, targetPivotY, nodePivotX, nodePivotY, isOpposite)
    if not targetNodeGo then
        return
    end
    -- print(targetNodeGo.name)
    if not parGo then
        parGo = UIModule.RootCanvas
    end
    if not targetPivotX then
        targetPivotX = 0.5
    end

    if not targetPivotY then
        targetPivotY = 0.5
    end

    if not nodePivotX then
        nodePivotX = 0.5
    end

    if not nodePivotY then
        nodePivotY = 0.5
    end

    --local cam = KTool.FindCameraForLayer(CS.UnityEngine.LayerMask.NameToLayer("UI"))
    local cam = UIModule.RootCanvas.defaultCamera
    local topLayerRt = parGo.transform:GetComponent("RectTransform")
    local posBasic = CS.UnityEngine.RectTransformUtility.WorldToScreenPoint(cam, targetNodeGo.transform.position)
    local isSuccess
    --基于目标自身pivot转出的坐标
    isSuccess, posBasic = CS.UnityEngine.RectTransformUtility.ScreenPointToLocalPointInRectangle(topLayerRt, posBasic, cam)
    local targetRt = targetNodeGo.transform:GetComponent(typeof(RectTransform))
    local targetPivot = targetRt.pivot
    local targetRect = CfUtils.GetNodeRect(targetNodeGo)
    --以目标节点的中心点偏移
    local targetPos = Vector3(posBasic.x - (targetPivot.x - targetPivotX) * targetRect.width, posBasic.y - (targetPivot.y - targetPivotY) * targetRect.height, 0)

    local nodeOffsetX = 0
    local nodeOffsetY = 0
    if nodeGo then
        local nodeRt = nodeGo.transform:GetComponent(typeof(RectTransform)) or {}
        local nodeRect = CfUtils.GetNodeRect(nodeGo, isOpposite)
        nodeOffsetX = (nodePivotX - nodeRt.pivot.x) * nodeRect.width
        nodeOffsetY = (nodePivotY - nodeRt.pivot.y) * nodeRect.height
    end

    --以自身节点的中心点偏移
    targetPos = Vector3(targetPos.x - nodeOffsetX, targetPos.y - nodeOffsetY, 0)
    return targetPos
end

---GetNodeRect 获取节点的Rect
---@param nodeGo UnityEngine.GameObject
---@param isOpposite boolean @ 是否相反
---@return table @ { width : number, width : number }
function CfUtils.GetNodeRect(nodeGo, isOpposite)
    local t = {
        width = 0,
        height = 0
    }

    if not nodeGo then
        return t
    end
    local nodeRt = nodeGo.transform:GetComponent(typeof(RectTransform))
    local nodeRect = nodeRt.rect
    local nodeScale = nodeGo.transform.localScale

    local contentSizeFitter = nodeGo.transform:GetComponent(typeof(ContentSizeFitter))
    if contentSizeFitter then
        --强刷一下 矫正size
        CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(nodeRt)
        if contentSizeFitter.horizontalFit == ContentSizeFitter.FitMode.PreferredSize then
            t.width = CS.UnityEngine.UI.LayoutUtility.GetPreferredWidth(nodeRt) * nodeScale.x
        else
            t.width = nodeRect.width * nodeScale.x
        end

        if contentSizeFitter.verticalFit == ContentSizeFitter.FitMode.PreferredSize then
            t.height = CS.UnityEngine.UI.LayoutUtility.GetPreferredHeight(nodeRt) * nodeScale.y
        else
            t.height = nodeRect.height * nodeScale.y
        end
    else
        t.width = nodeRect.width * nodeScale.x
        t.height = nodeRect.height * nodeScale.y
    end
    if isOpposite then
        local num = t.width
        t.width = t.height
        t.height = num
    end

    return t
end

