---IsPosInScreenRect 一个ui是否与屏幕相交
---@param pos Vector3 @ ui坐标
---@param goW integer @ 宽度
---@param goH integer @ 高度
---@return boolean
function CfUtils.IsPosInScreenRect(pos, goW, goH)
    ---@type UnityEngine.RectTransform
    local rootRt = UIModule.RootCanvas.transform:GetComponent("RectTransform")
    local screenW, screenH = rootRt.rect.width / 2, rootRt.rect.height / 2
    if pos.x - goW >= -screenW and pos.x + goW <= screenW and pos.y - goH >= -screenH and pos.y + goH <= screenH then
        return true
    end
    return false
end

---IsPosHighInScreenRect 一个uig高度是否与超出屏幕
---@param pos Vector3 @ ui坐标
---@param goH integer @ 高度
---@return boolean, integer
function CfUtils.IsPosHighInScreenRect(pos, goH)
    local rootRt = UIModule.RootCanvas.transform:GetComponent("RectTransform")
    local screenH = rootRt.rect.height / 2
    if pos.y - goH < -screenH then
        return false, math.abs(math.abs(pos.y - goH) - math.abs(screenH))
    elseif pos.y + goH > screenH then
        return false, -math.abs(math.abs(pos.y + goH) - math.abs(screenH))
    end
    return true, 0
end

---IsPosWidthInScreenRect 一个uig宽度是否与超出屏幕
---@param pos Vector3 @ ui坐标
---@param goW integer @ 宽度
---@return boolean, integer
function CfUtils.IsPosWidthInScreenRect(pos, goW)
    local rootRt = UIModule.RootCanvas.transform:GetComponent("RectTransform")
    local screenW = rootRt.rect.width / 2
    if pos.x - goW < -screenW then
        return false, math.abs(math.abs(pos.x - goW) - math.abs(screenW))
    elseif pos.x + goW > screenW then
        return false, -math.abs(math.abs(pos.x + goW) - math.abs(screenW))
    end
    return true, 0
end

---GetFixPosOffsetXInScreenRect
---@param pos Vector3 @ ui坐标
---@param goW integer @ 宽度
---@return integer
function CfUtils.GetFixPosOffsetXInScreenRect(pos, goW)
    local rootRt = UIModule.RootCanvas.transform:GetComponent("RectTransform")
    local screenW = rootRt.rect.width / 2
    if pos.x - goW >= -screenW and pos.x + goW <= screenW then
        return 0
    end
    if pos.x - goW < -screenW then
        return -screenW - (pos.x - goW)
    end
    if pos.x + goW > screenW then
        return screenW - (pos.x + goW)
    end
    return 0
end

