function CfUtils.isInVailId(id)
    local isVail = true 
    ---@type SettingMgr
    local SettingMgr = SettingMgr
    local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting8939)
    local isHave = tableFile:HasPrimaryKey(tostring(id))
    ---@type SDKService
    local SDKService = import('Game.Entry.SDKService'):GetInstance()
    if isHave then
        local row = tableFile:GetByPrimaryKey(id)
        local isSwitch = 1 
        local key = ""
        if SDKService:IsCN() or SDKService:IsDuoLe() then
            key = "cnSwitch"
        elseif SDKService:IsSea() or SDKService:isIndo()   then    
            key = "seaSwitch"
        elseif SDKService:IsJP() or SDKService:IsDmm() then   
            key = "jpSwitch"
        elseif SDKService:IsKr()  or SDKService:IsOneStore() then 
            key = "krSwitch"
        elseif SDKService:IsTw() or SDKService:IsQoo() then 
            key = "twSwitch"
        elseif SDKService:IsZm()  then    
            key = "zmSwitch"
        end 
        if string.len(key) > 0 then
            isSwitch = parse_number(row,key,0) 
        end
        if isSwitch == 0 then
            return false
        end
    end
    return true
end

