--- 额外追加刷新顶部资源栏（一二级货币是固定的）
---@param extraGoodsIds integer[] @ 额外追加的资源id列表
---@param isForward boolean | nil @ 前面插入还是后方插入
---@param isDisableSecondaryCurrency boolean | nil @ 是否禁用二级货币
function CfUtils.RefreshTopGoodsNew(extraGoodsIds, isForward, isDisableSecondaryCurrency)
    local currencyLisst = {}
    ---@type ServerDifferenceMgr
    local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
    if ServerDifferenceMgr:IsSecondaryCurrencyEnable() and not isDisableSecondaryCurrency then
        local primaryCurrencyId   = checkInt(checkTable(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 17)).num)  -- 一级货币
        local secondaryCurrencyId = checkInt(checkTable(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 19)).num)  -- 二级货币
        if primaryCurrencyId > 0 then
            table.insert(currencyLisst, primaryCurrencyId)
        end
        if secondaryCurrencyId then
            table.insert(currencyLisst, secondaryCurrencyId)
        end
    else
        currencyLisst = { Constants.Currency.FreeDiamondId }
    end
    if isForward then
        table.insertto(checkTable(extraGoodsIds), currencyLisst)
        currencyLisst = extraGoodsIds
    else
        table.insertto(currencyLisst, checkTable(extraGoodsIds))
    end
    CfUtils.RefreshTopGoods(currencyLisst)
end


