    return Vector3(x, y, 0)
end

---GetTimeHMS  返回 xx:xx:xx
---@param second integer @ 秒数
---@return string
function CfUtils.GetTimeHMS(second)
    if second <= 0 then
        return "00:00:00"
    end
    local d, h, m, s
    h = math.floor(second / 3600)

    d = math.floor(h / 24)
    --如果大于一天返回天数
    if d > 0 then
        return localize("_num_天", { _num_ = d })
    end
    m = math.floor((second - 3600 * h) / 60)
    s = math.floor(second - 3600 * h - 60 * m)

    h = h < 10 and "0" .. h or h
    m = m < 10 and "0" .. m or m
    s = s < 10 and "0" .. s or s
    return h .. ":" .. m .. ":" .. s
end

---GetTimeHMS5  返回 xx:xx:xx
---@param second integer @ 秒数
---@return string
function CfUtils.GetTimeHMS5(second)
    local d, h, m, s
    h = math.floor(second / 3600)

    d = math.floor(h / 24)
    --如果大于一天返回天数
    if d > 0 then
        return localize("本轮剩余_num_天", { _num_ = d })
    end
    m = math.floor((second - 3600 * h) / 60)
    s = math.floor(second - 3600 * h - 60 * m)

    h = h < 10 and "0" .. h or h
    m = m < 10 and "0" .. m or m
    s = s < 10 and "0" .. s or s
    return localize("_h_时_m_分", { _h_ = h, _m_ = m })
end

---@param second integer @ 秒数
---@return string
function CfUtils.GetTimeHMS2(second)
    local d, h, m, s
    h = math.floor(second / 3600)

    d = math.floor(h / 24)
    m = math.floor((second - 3600 * h) / 60)
    s = math.floor(second - 3600 * h - 60 * m)

    h = h < 10 and "0" .. h or h
    m = m < 10 and "0" .. m or m
    s = s < 10 and "0" .. s or s
    return h .. ":" .. m .. ":" .. s
end

---GetTimeHMS  返回 xx:xx:xx
---@param second integer @ 秒数
---@param size integer
---@return integer
function CfUtils.GetTimeHMS3(second, size)
    local d, h, m, s
    h = math.floor(second / 3600)

    d = math.floor(h / 24)
    --如果大于一天返回天数
    if d > 0 then
        return localize("<size=_size_>_num_</size> 天", { _size_ = size, _num_ = d })
    end
    m = math.floor((second - 3600 * h) / 60)
    s = math.floor(second - 3600 * h - 60 * m)

    h = h < 10 and "0" .. h or h
    m = m < 10 and "0" .. m or m
    s = s < 10 and "0" .. s or s
    return h .. ":" .. m .. ":" .. s
end

function CfUtils.GetTimeDYDHMS(tick)
    local str = os.date(localize("%Y年%m月%d日%H时%M分%S秒"), tick)
    return str
end

---@param second integer @ 秒数
---@param color string @颜色标签
---@return string
function CfUtils.GetTimeHMS4(second,color)
    local d, h, m, s
    h = math.floor(second / 3600)

    d = math.floor(h / 24)
    --如果大于一天返回天数
    if d > 0 then
        if not isNull(color) then
            return localize("_num1_天_num2_小时", { _num1_ = string.fmt('<color=#%1>%2</color>', color, tostring(d)) , _num2_ = string.fmt('<color=#%1>%2</color>', color, tostring(h - d * 24))})
        else
            return localize("_num1_天_num2_小时", { _num1_ = d , _num2_ = h - d * 24})
        end
    end

    m = math.floor((second - 3600 * h) / 60)
    if h >= 1 then
        if not isNull(color) then
            return localize("_num1_小时_num2_分", { _num1_ = string.fmt('<color=#%1>%2</color>', color, tostring(h)), _num2_ = string.fmt('<color=#%1>%2</color>', color, tostring(m))})
        else
            return localize("_num1_小时_num2_分", { _num1_ = h, _num2_ = m})
        end
    end
    s = math.floor(second - 3600 * h - 60 * m)

    h = h < 10 and "0" .. h or h
    m = m < 10 and "0" .. m or m
    s = s < 10 and "0" .. s or s
    if not isNull(color) then
        return string.fmt('<color=#%1>%2</color>', color, tostring(h .. ":" .. m .. ":" .. s))
    else
        return h .. ":" .. m .. ":" .. s
    end
end

---@param second integer @ 秒数
---@return string
function CfUtils.GetTimeHMS7(second)
    local d, h, m, s
    h = math.floor(second / 3600)

    d = math.floor(h / 24)
    --如果大于一天返回天数
    if d > 0 then
        return localize("_num1_天_num2_小时", { _num1_ = d, _num2_ = h - d * 24 })
    end

    m = math.floor((second - 3600 * h) / 60)
    if h >= 1 then
        return localize("0天_num1_小时", { _num1_ = h })
    end
    s = math.floor(second - 3600 * h - 60 * m)

    return localize("不足1小时")
end

---@param seconds integer @ 秒数
---@return string
function CfUtils.GetTimeHumanize(seconds)
    local ts = TimeSpan.FromSeconds(checkNumber(seconds))
    local t = {}
    if ts.Days > 0 then
        table.insert(t, localize('_days_天', { _days_ = ts.Days }))
        if ts.Hours > 0 then
            table.insert(t, localize('_hour_小时', { _hour_ = ts.Hours }))
        end
    else
        if ts.Hours > 0 then
            table.insert(t, localize('_hour_小时', { _hour_ = ts.Hours }))
        end
        if ts.Minutes > 0 then
            table.insert(t, localize('_minute_分钟', { _minute_ = ts.Minutes }))
        end
    end
    return table.concat(t)
end

