---GetTimeHMS9  返回 xx:xx:xx
---@param second integer @ 秒数
---@return string
function CfUtils.GetTimeHMS9(second)
    local d, h, m, s
    local floorD, floorH, floorM

    d = math.floor((math.floor(second / 3600)) / 24)
    floorD = 86400 * d
    h = math.floor((second - floorD) / 3600)
    floorH = 3600 * h
    m = math.floor((second - floorD - floorH) / 60)
    floorM = 60 * m
    s = math.floor(second - floorD - floorH - floorM)

    local str = string.format("%02d:%02d:%02d", h, m, s)
    --如果大于一天返回天数
    if d > 0 then
        return localize("_num_天_time_", { _num_ = d, _time_ = str })
    end

    return str
end
---@param second integer @ 秒数
---@return table 返回具体时间和时间叙述
function CfUtils.GetTimeData(second)
    local t = { time = 0, timeDesec = "" }
    if second > 86400 then
        t.time = math.ceil(second / 86400)
        t.timeDesec = localize("剩余天数")
    elseif second > 3600 and second < 86400 then
        t.time = math.ceil(second / 3600)
        t.timeDesec = localize("剩余小时")
    else
        t.time = math.ceil(second / 60)
        t.timeDesec = localize("剩余分钟")
    end
    return t
end

