---@param uiArgument Engine.UI.UILuaDialog
---@return table
function CfUtils.DialogSafeParameters(controller)
    if isNull(controller) then
        return
    end
    if isNull(controller.Argument.parameters) then
        local uiArgument = controller.Argument
        local arguments = {
            id = uiArgument.id,
            path = uiArgument.path,
            status = uiArgument.status,
            isBackable = uiArgument.isBackable,
            extra = uiArgument.extra,
            hasExcluded = uiArgument.hasExcluded,
            parameters = {}
        }
        controller.Argument = arguments
    end
    return controller.Argument.parameters
end

---GsubStr  字符串替换
---@param content string
---@param valueTab table
---@param targetStr string
function CfUtils.GsubStr(content, valueTab, targetStr)
    if not content then
        return ""
    end

    if not valueTab or #valueTab <= 0 then
        return content
    end

    targetStr = targetStr ~= nil and targetStr or "_target_num_"
    local str
    for i = 1, #valueTab do
        str = string.gsub(content, targetStr, valueTab)
    end
    return str
end

