---GetTeamMemberDojo  返回一个队伍队员数据
---@param data table
---@return TeamMemberDojo
function CfUtils.GetTeamMemberDojo(data)
    local dojo = {}
    if not data or checkNumber(data.refId) == 0 then
        return dojo
    end
    ---@type TeamMemberDojo
    local dojo = import("Game.Dojo.TeamMemberDojo").New()
    local cardId, fettersCardId = 0, 0
    --目前除了自己的卡牌其他的卡牌id都是refid
    if checkNumber(data.type) == Constants.TeamMemberType.PlayerCard then
        local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        local cardDojo = comp:GetCardById(data.refId)
        if cardDojo then
            cardId = cardDojo.cardId
        end

        if checkNumber(data.fettersId) > 0 then
            cardDojo = comp:GetCardById(data.fettersId)
            if cardDojo then
                fettersCardId = cardDojo.cardId
            end
        end
    else
        cardId = (checkNumber(data.cardId) ~= 0 and data.cardId or data.refId)
        fettersCardId = (checkNumber(data.fettersCardId) ~= 0 and data.fettersCardId or data.fettersId)
    end
    dojo:Fill({
        type = checkNumber(data.type),
        refId = checkString(data.refId),
        cardId = checkString(cardId),
        fettersId = checkNumber(data.fettersId),
        fettersCardId = checkNumber(fettersCardId),
    })
    return dojo
end
