---GetGroupArrays 按数量切割数组
---@param datas table
---@param maxNum integer
---@return table
function CfUtils.GetGroupArrays(datas, maxNum)
    if not datas or #datas < 1 then
        return datas
    end
    maxNum = checkInt(maxNum)
    maxNum = maxNum > 0 and maxNum or 1

    local rData = {}
    local count = 0
    local k = 0
    while (k < #datas) do
        local t = {}
        t._tarType = 1          --标记
        for i = 1, maxNum do
            if datas[i + k] then
                table.insert(t, datas[i + k])
            else
                table.insert(rData, t)
                return rData
            end

            if i == maxNum then
                table.insert(rData, t)
                count = count + 1
                k = count * maxNum
            end
        end
    end
    return rData
end

