--迷宫事件界面的动画
---@param goPar UnityEngine.Transform
---@param point MazeMapPointDojo
---@return Engine.Modules.AbstractResourceLoader
function CfUtils.FillEnentAnim(goPar, point)
    if not goPar or not point then
        return nil
    end
    --动画
    local amName = "MazeAnim_" .. checkString(point.type)
    local amNode = goPar.transform:Find(amName)
    local loader
    if not amNode then
        local loader = CS.Engine.Modules.ResourceModule.LoadBundleSync(CfUtils.GetMazeViewPointAnimPath(point), nil, true)
        if loader.IsSuccess then
            amNode = CfUtils.InstantiateGo(loader.ResultObject, goPar)
        end

        if amNode then
            amNode.name = amName
            KTool.SetActive(amNode, true)
        end
    end
    return loader
end

