---GetQuestVoRewards  获取关卡奖励
---@param rewardType integer
---@return table[]
function CfUtils.GetQuestVoRewards(questVo, rewardType)
    if not questVo then
        return nil
    end
    local rewardData
    local rewardNums

    if not rewardType or checkNumber(rewardType) == Constants.QuestRewardType.FristRewards then
        if questVo.fristRewards and questVo.fristRewards ~= "0" and questVo.fristRewards ~= "" then
            rewardData = string.split(questVo.fristRewards, ";")
        end
        if questVo.fristRewardsNum and questVo.fristRewardsNum ~= "0" and questVo.fristRewardsNum ~= "" then
            rewardNums = string.split(questVo.fristRewardsNum, ";")
        end

    elseif checkNumber(rewardType) == Constants.QuestRewardType.StarRewardId then
        if questVo.starRewardId and questVo.starRewardId ~= "0" and questVo.starRewardId ~= "" then
            rewardData = string.split(questVo.starRewardId, ";")
        end
        if questVo.starRewardNum and questVo.starRewardNum ~= "0" and questVo.starRewardNum ~= "" then
            rewardNums = string.split(questVo.starRewardNum, ";")
        end

    elseif checkNumber(rewardType) == Constants.QuestRewardType.RegularReward then
        if questVo.regularReward and questVo.regularReward ~= "0" and questVo.regularReward ~= "" then
            rewardData = string.split(questVo.regularReward, ";")
        end
        if questVo.regularRewardNum and questVo.regularRewardNum ~= "0" and questVo.regularRewardNum ~= "" then
            rewardNums = string.split(questVo.regularRewardNum, ";")
        end

    elseif checkNumber(rewardType) == Constants.QuestRewardType.RareReward then
        if questVo.rareReward and questVo.rareReward ~= "0" and questVo.rareReward ~= "" then
            rewardData = string.split(questVo.rareReward, ";")
        end
        if questVo.rareRewardMinNum and questVo.rareRewardMinNum ~= "0" and questVo.rareRewardMinNum ~= "" then
            --rewardNums = string.split(questVo.rareRewardMinNum, ";")
            rewardNums = {}
        end
    end

    return CfUtils.GetRewardData(rewardData, rewardNums)
end

---GetRewardData  获取奖励数据
---@param rewards integer[] @ id集合
---@param rewardNums integer[] @ 数量集合
---@return table[]
function CfUtils.GetRewardData(rewards, rewardNums)
    if not rewards or #rewards <= 0 then
        return {}
    end

    local rewardDatas = {}
    for i = 1, #rewards do
        local id = rewards[i]
        local num
        if rewardNums then
            num = rewardNums[i]
        end
        local reward = {
            ["id"] = id,
            ["num"] = num
        }

        table.insert(rewardDatas, reward)
    end
    return CfUtils.SortRewards(rewardDatas)
end

--奖励排序规则
---@param items table[]
---@return table[]
function CfUtils.SortRewards(items)
    if not items or #items <= 0 then
        return items
    end
    local itemsReturn = clone(items)
    table.sort(itemsReturn, function(a, b)
        local item1 = GoodsConfMgr:GetInstance():GetGoodsVoById(a.id)
        local item2 = GoodsConfMgr:GetInstance():GetGoodsVoById(b.id)

        if not item1 then
            return true
        elseif not item2 then
            return false
        end

        if checkNumber(item1.quality) > checkNumber(item2.quality) then
            return true
        elseif checkNumber(item1.quality) == checkNumber(item2.quality) then
            if checkNumber(a.id) < checkNumber(b.id) then
                return true
            end
        end
        return false
    end)
    return itemsReturn
end

---IsHaveReward  奖励列表是否含有此id奖励
---@param rewards table
---@param id integer @ 自己造的奖励的id
---@return boolean
function CfUtils.IsHaveReward(rewards, id)
    if not rewards or not id then
        return false
    end

    for k, v in pairs(rewards) do
        if checkNumber(v.id) == checkNumber(id) then
            return true
        end
    end
    return false
end

---GetUseItemByStrenth  使用目标体力需要消耗的道具,  1.体力，2.猫科拉（补充体力期限道具）， 3.奥博兑换
---@param targetStrength integer @ 需要的体力数
---@param isClientShow boolean  是否是客户端显示用,区分服务器数据
---@param unusedGoods table @ {"300001",}不能使用的道具
---@return table, boolean
function CfUtils.GetUseItemByStrenth(targetStrength, isClientShow, unusedGoods)
    targetStrength = checkNumber(targetStrength)

    local isCanPay = true    --身上的物品是否可以支付兑换需要的体力
    local useItems = {}

    --使用的物品, 第一个是体力，显示用
    local hpItemm, targetStrength = CfUtils.GetHpItemByStrenth(targetStrength)
    if isClientShow then
        table.insert(useItems, hpItemm)
    end
    if targetStrength <= 0 then
        return useItems, isCanPay
    end

    --取需要的期限补充体力物品
    local usableGoods, targetStrength = GoodsUtils.GetUseGoodsAddHp(targetStrength)
    if isClientShow then
        usableGoods = GoodsUtils.MergeUsableGoods(usableGoods)
    end
    if usableGoods then
        for k, v in pairs(usableGoods) do
            table.insert(useItems, v)
        end
    end
    if targetStrength <= 0 then
        return useItems, isCanPay
    end
    --取非期限物品
    --所有的可兑换体力非期限物品
    local commonItems = {}
    local ExchangeStrengthTab = CfUtils.GetCfTable(AutoIds.IdSetting302)
    for k, v in pairs(ExchangeStrengthTab) do
        local goodsId = parse_string(v, "itemId")
        local type = GoodsUtils.GetIdType(goodsId)
        --if type ~= Constants.IDType.GoodsUsable and (not table.keyof(unusedGoods, goodsId)) then
        if (not table.keyof(unusedGoods, goodsId)) then
            local item = {
                goodsId = goodsId,
                num = 0,
                isEnough = true,
            }
            table.insert(commonItems, item)
        end
    end
    for k, v in pairs(commonItems) do
        local t = {
            goodsId = v.goodsId,
            playerItemId = v.playerItemId,
            num = 0,
            isEnough = true, --显示判断用
        }
        --如果目标体力大于0 才判断
        if targetStrength > 0 then
            local needNum = CfUtils.GetItemNumByStrenth(t.goodsId, targetStrength)
            local haseNum = GoodsUtils.GetThingNo(t.goodsId, t.playerItemId)

            local exchangeStrengthVo = CfUtils.GetCfVo(AutoIds.IdSetting302, "ExchangeStrengthVo", t.goodsId)
            if haseNum >= needNum then
                t.num = needNum
                --不够
            else
                t.num = math.floor(haseNum / checkNumber(exchangeStrengthVo.itemIdCost))
            end

            targetStrength = targetStrength - t.num * (checkNumber(exchangeStrengthVo.getItemCost) / checkNumber(exchangeStrengthVo.itemIdCost))
            if k == #commonItems and targetStrength > 0 then
                t.isEnough = false
                t.num = needNum
                isCanPay = false
            end
            if checkNumber(t.num) > 0 then
                table.insert(useItems, t)
            end
        else
            if checkNumber(t.num) > 0 then
                table.insert(useItems, t)
            end
        end
    end
    if targetStrength > 0 then
        isCanPay = false
    end
    if not isCanPay then
        for k, v in pairs(useItems) do
            v.isEnough = false
        end
    end

    return useItems, isCanPay
end

---GetPlayerIDNum
---获取 玩家身份 Id
---@param pId integer
---@return string[]
function CfUtils.GetPlayerIDNum(pId)
    local playerId = pId
    if playerId == -1 then
        return playerId
    end
    if checkInt(playerId) < 100000 then
        playerId = checkInt(playerId) + 100000
    end
    local strPart_1 = string.sub(checkString(playerId), 1, 4)
    local strPart_2 = string.sub(checkString(playerId), 5, #checkString(playerId))
    local showPatr_1 = string.gsub(string.format("%#x", strPart_1), "0x", "")
    local showPatr_2 = string.gsub(string.format("%#x", strPart_2), "0x", "")

    local showPatr_3 = string.gsub(string.format("%#x", #checkString(playerId)), "0x", "")
    return { showPatr_1, showPatr_2, showPatr_3 }
end

