--获取使用体力的数据
---@param targetStrength integer
---@return table, integer
function CfUtils.GetHpItemByStrenth(targetStrength)
    targetStrength = checkNumber(targetStrength)
    local hpItem = {
        goodsId = Constants.Currency.HpId,
        num = 0,
        isEnough = true,
    }

    local playerStrength = checkNumber(GoodsUtils.GetThingNo(Constants.Currency.HpId))
    --如果拥有的体力大于需要的体力
    if playerStrength >= targetStrength then
        hpItem.num = targetStrength
    else
        hpItem.num = playerStrength
    end
    --剩余体力
    targetStrength = targetStrength - playerStrength
    return hpItem, targetStrength
end

