---GetItemNumByStrenth  使用目标体力需要消耗的道具数量
---@param itemId integer @ 物品Id
---@param targetStrength integer @ 需要的体力数
---@return integer
function CfUtils.GetItemNumByStrenth(itemId, targetStrength)
    local num = 0
    local exchangeStrengthVo = CfUtils.GetCfVo(AutoIds.IdSetting302, "ExchangeStrengthVo", itemId)
    if not exchangeStrengthVo then
        return num
    end

    --总体力/（物品兑换体力 / 物消耗数量） 向上取整
    num = math.ceil(targetStrength / (checkNumber(exchangeStrengthVo.getItemCost) / checkNumber(exchangeStrengthVo.itemIdCost)))
    num = math.ceil(num / checkNumber(exchangeStrengthVo.itemIdCost)) * checkNumber(exchangeStrengthVo.itemIdCost)
    return num
end

---GetFinNumUseGood  使用道具兑换之后增加的道具数量
---@param targetGoodsId integer @ 兑换物品id
---@param items table @ 使用的物品
---@return integer
function CfUtils.GetFinNumUseGood(targetGoodsId, items)
    if not targetGoodsId and not items then
        return
    end

    local num = 0
    for k, v in pairs(checkTable(items)) do
        if checkNumber(v.goodsId) == checkNumber(targetGoodsId) then
            --num = num - v.num
        else
            local vo = CfUtils.GetCfVo(AutoIds.IdSetting302, "ExchangeStrengthVo", v.goodsId)
            if vo then
                num = num + checkNumber(vo.getItemCost) / checkNumber(vo.itemIdCost) * v.num
            end
        end
    end
    return num
end

