---GetAnimatorTime 获取一个Animator动画的时间
---@param go UnityEngine.GameObject
---@param name string @ 动作名字
---@return integer
function CfUtils.GetAnimatorTime(go, name)
    local length = 0
    if not go then
        return length
    end
    local animator = go.gameObject:GetComponent(typeof(Animator))
    if isNull(animator) then
        return length
    end
    local clips = animator.runtimeAnimatorController.animationClips
    for i = 1, clips.Length do
        ---@type UnityEngine.AnimationClip
        local v = clips[i - 1]
        if v.name == checkString(name) then
            length = checkNumber(v.length) + length
            return length
        end
    end
    return length
end

---GetAnimatorTime 获取一个Animation动画的时间
---@param go UnityEngine.GameObject
---@param name string @ 动作名字
---@return integer
function CfUtils.GetAnimationTime(go, name)
    local length = 0
    if not go then
        return length
    end
    local animation = go.gameObject:GetComponent(typeof(Animation))
    if isNull(animation) then
        return length
    end
    local clip = animation:GetClip(name)
    if clip then
        length = clip.length
    end
    return length
end

