    animation.playAutomatically = (isAuto == true)
end

---GetAnimatorTime 获取一个动画的当前状态信息
---@param go UnityEngine.GameObject
---@param layerIndex integer @ default 0
---@return UnityEngine.AnimatorStateInfo
function CfUtils.GetAnimatorStateInfo(go, layerIndex)
    local stateInfo = nil
    if not go then
        return stateInfo
    end
    ---@type UnityEngine.Animator
    local animator = go.gameObject:GetComponent(typeof(Animator))
    if isNull(animator) then
        return stateInfo
    end
    return animator:GetCurrentAnimatorStateInfo(checkInt(layerIndex))
end

---PlaySpine 播放一个spine动画
---@param go UnityEngine.GameObject
---@param name string @ 动作名字
---@param isLoop boolean @ 是否循环
function CfUtils.PlaySpine(go, name, isLoop)
    local spine = go.gameObject:GetComponent(typeof(SkeletonGraphic))
    if isNull(spine) then
        spine = go.gameObject:GetComponent(typeof(SkeletonAnimation))
    end
    if isNull(spine) then
