    end

    isLoop = (isLoop and true or false)
    return spine.AnimationState:SetAnimation(0, name, isLoop)
end

---SetSpineFlip 翻转一个spine动画
---@param go UnityEngine.GameObject
---@param isFlipX boolean @ 是否翻转X
---@param isFlipY boolean @ 是否翻转Y
function CfUtils.SetSpineFlip(go, isFlipX, isFlipY)
    local spine = go.gameObject:GetComponent(typeof(SkeletonGraphic))
    if isNull(spine) then
        spine = go.gameObject:GetComponent(typeof(SkeletonAnimation))
    end
    if isNull(spine) then
        return
    end
    isFlipX = (isFlipX and true or false) and -1 or 1
    if spine.Skeleton.ScaleX  ~= isFlipX then
        spine.Skeleton.ScaleX = isFlipX
    end
    
    isFlipY = (isFlipY and true or false) and -1 or 1
    if spine.Skeleton.ScaleY  ~= isFlipY then
        spine.Skeleton.ScaleY = isFlipY
    end
end

