---@param doCallback fun():void @ 需要执行的回调
---@return UnityEngine.Coroutine
function CfUtils.WaitCallbackSafeTo(doCallback)
    local conditionKey = 'WaitCallbackTo_'
    return CoStart(function()
        CfUtils.ConditionAppend(conditionKey)
        xTry(function()
            if doCallback then
                doCallback()
            end
            CfUtils.ConditionRemove(conditionKey)
        end, function(msg)
            CfUtils.ConditionRemove(conditionKey)
            printError(msg)
        end)
    end)
end


---@param go UnityEngine.GameObject
---@param state string @ 动画状态名字
---@param doCallback fun():void @ 动画播放完成执行的回调
---@return UnityEngine.Coroutine
function CfUtils.WaitPlayAnimatorTo(go, state, doCallback)
    if not go then
        return
    end
    if not state then
        return
    end

    ---@type UnityEngine.Animator
    local animator = go.transform:GetComponent(typeof(Animator))
    if isNull(animator) then
        return
    end

    local conditionKey = 'CfUtils_WaitPlayAnimatorTo_' .. tostring(animator)
    local aniTime = animator:GetTimeByAniName(state)
    return CoStart(function()
        CfUtils.ConditionAppend(conditionKey)
        CfUtils.PlayAnimator(go, state)
        CoYield(aniTime)
        CfUtils.ConditionRemove(conditionKey)
        if doCallback then
            doCallback()
        end
    end)
end

---@param go UnityEngine.GameObject
---@param state string @ 动画名字
---@param doCallback fun():void @ 动画播放完成执行的回调
---@return UnityEngine.Coroutine
function CfUtils.WaitPlayAnimationTo(go, name, doCallback)
    if not go then
        return
    end
    if not name then
        return
    end

    ---@type UnityEngine.Animation
    local animator = go.transform:GetComponent(typeof(Animation))
    if isNull(animator) then
        return
    end

    local time = CfUtils.GetAnimationTime(go, name)
    if time > 0 then
        local conditionKey = 'CfUtils_WaitPlayAnimationTo_' .. tostring(animator)
        return CoStart(function()
            CfUtils.ConditionAppend(conditionKey)
            CfUtils.PlayAnimation(go, name)
            CoYield(time)
            CfUtils.ConditionRemove(conditionKey)
            if doCallback then
                doCallback()
            end
        end)
    end
end

--- 设置动画控件的 wrapMode 为 ClampForever（当播放到结尾的时候，动画总是处于最后一帧的采样状态）
--- 可用于解决 PlayQueued 动画时，最后一帧不生效的问题
---@param go UnityEngine.GameObject @ 挂有该动画的Go
function CfUtils.SetAnimationWarpModeToClampForever(go)
    if not go then return end
    ---@type UnityEngine.Animation
    local animator = go.transform:GetComponent(typeof(Animation))
    if isNull(animator) then
        return
    end
    animator.wrapMode = CS.UnityEngine.WrapMode.ClampForever
end

---@param go UnityEngine.GameObject @ 挂有该动画的Go
---@param delayCount integer @ 延迟动画播放次数
---@param showAnimName string | nil @ 显示动画名，默认 UI_Common_List_Cell_Show
---@param waitAnimName string | nil @ 延迟动画名字，默认 UI_Common_List_Cell_Wait
---@param isClampMode boolean | nil @ 是否启用 WrapMode.ClampForever 模式，默认false。（可用于解决最后一帧时不生效的问题）
function CfUtils.PlayDelayShowAnimation(go, delayCount, showAnimName, waitAnimName, isClampMode)
    if not go then return end
    ---@type UnityEngine.Animation
    local animator = go.transform:GetComponent(typeof(Animation))
    if isNull(animator) then
        return
    end
    waitAnimName = waitAnimName or 'UI_Common_List_Cell_Wait'
    showAnimName = showAnimName or 'UI_Common_List_Cell_Show'
    animator:Stop()  -- 需要stop在播的play动画，PlayQueued貌似不会替换
    if isClampMode then
        CfUtils.SetAnimationWarpModeToClampForever(go)
    end
    for i = 1, checkInt(delayCount) do
        animator:PlayQueued(waitAnimName)
    end
    animator:PlayQueued(showAnimName)
end


---PlayAnimator 播放通用的延时出现动画Ani_CommonCellShowAlphaX100Wait
---@param go UnityEngine.GameObject 挂有该动画的Go
---@param index integer
---@param interval number 间隔时间
---@param initialTime number 出现的时间
---@param cb function 在等待时间结束后执行 （使用的时候 一定要注意回调是延迟执行 所以要小心对象为空 界面被移除 要做空判定）
---@return UnityEngine.Coroutine
function CfUtils.PlayDelayShowAnimate(go, index, interval, initialTime, name,cb)
    if not go then
        return nil
    end
    if isNull(initialTime) then
        initialTime = 0
    end
    if isNull(interval) then
        interval = 0.1
    end
    local animator = nil
    if iskindof(go, typeof(Animator)) then
        animator = go
    else
        animator = go.transform:GetComponent(typeof(Animator))
    end
    if isNull(animator) then
        if iskindof(go, typeof(Animation)) then
            animator = go
        else
            animator = go.transform:GetComponent(typeof(Animation))
        end
    else
        animator:Rebind()
    end
    return cs_coroutine.start(function()
        coroutine.yield(CS.UnityEngine.WaitForSeconds(initialTime + interval * index))
        if not isNull(cb) then
            cb()
        end
        if not isNull(go) and CfUtils.IsActiveInHierarchy(go) then
            if name ~= nil then
                animator:Play(name)
            elseif index == 0 then
                animator:Play("Default")
            else
                animator:Play("Go")
            end
        end
    end)
end

