function CfUtils.GetSpineTime(go, name)
    local spine = go.gameObject:GetComponent(typeof(SkeletonGraphic))
    if isNull(spine) then
        spine = go.gameObject:GetComponent(typeof(SkeletonAnimation))
    end
    if isNull(spine) then
        return 0
    end

    local animation = spine.Skeleton.Data:FindAnimation(name)
    if animation then
        return animation.Duration
    end
    return 0
end

