---PlayScaleAnimator 放大缩小的动画
---@param go UnityEngine.GameObject
---@param time number
---@param scaleFNum number
---@param scaleTNum number
---@param alphaFNum number
---@param alphaTNum number
function CfUtils.PlayScaleAndAlphaAnimator(go, time, scaleFNum, scaleTNum, alphaFNum, alphaTNum)
    if not go then
        return
    end

    local canvasGroup = go.transform:GetComponent(typeof(CanvasGroup))

    local scaleDis = scaleTNum - scaleFNum
    local alphaDis = alphaTNum - alphaFNum
    CfUtils.DoTween(time, function(updateValue)
        local curNum = scaleFNum + updateValue * scaleDis
        local scaleCur = Vector3(curNum, curNum, curNum)
        go.transform.localScale = scaleCur
        canvasGroup.alpha = alphaFNum + alphaDis * updateValue
    end)
end

---@param go UnityEngine.GameObject
---@param time number
---@param alphaFNum number
---@param alphaTNum number
function CfUtils.PlayAlphaAnimator(go, time, alphaFNum, alphaTNum)
    if not go then
        return
    end

    local canvasGroup = go.transform:GetComponent(typeof(CanvasGroup))
    local alphaDis = alphaTNum - alphaFNum
    CfUtils.DoTween(time, function(updateValue)
        canvasGroup.alpha = alphaFNum + alphaDis * updateValue
    end)
end

--获取网络新号强度
---@return Constants.PingLevel
function CfUtils.GetPingLevel()
    local level = (200 - checkNumber(KNManager.ping)) / 200
    --如果没连接
    if not KNManager.isConnected then
        return Constants.PingLevel.None
    end

    level = (level < 0 and 0 or level)
    local num = Constants.PingLevel.Low
    if level > 0.6 then
        num = Constants.PingLevel.High
    elseif level > 0.3 then
        num = Constants.PingLevel.Middle
    end

    return num
end

