---GetLocalData 获取本地数据
---@param key string
---@param default any | nil
---@return string
function CfUtils.WriteAutoLoginData2(str)
    local function encodeBase64(source_str)
        local b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
        local s64 = ''
        local str = source_str

        while #str > 0 do
            local bytes_num = 0
            local buf = 0

            for byte_cnt = 1, 3 do
                buf = (buf * 256)
                if #str > 0 then
                    buf = buf + string.byte(str, 1, 1)
                    str = string.sub(str, 2)
                    bytes_num = bytes_num + 1
                end
            end

            for group_cnt = 1, (bytes_num + 1) do
                local b64char = math.fmod(math.floor(buf / 262144), 64) + 1
                s64 = s64 .. string.sub(b64chars, b64char, b64char)
                buf = buf * 64
            end

            for fill_cnt = 1, (3 - bytes_num) do
                s64 = s64 .. '='
            end
        end

        return s64
    end

    local path = CS.UnityEngine.Application.persistentDataPath
    function subString(str, k)
        local ts = string.reverse(str)
        local _, i = string.find(ts, k)
        local m = string.len(ts) - i + 1
        return string.sub(str, 1, m)
    end

    local strIp = socket.dns.toip(socket.dns.gethostname())
    path = CS.Engine.Lib.PathUtility.Combine(path, strIp .. ".txt")
    print(path)
    --写
    --io.writeFile(path, encodeBase64(str))
    CS.System.IO.File.WriteAllText(path, encodeBase64(str))
end

---GetLocalData2 获取本地数据
---@return string
function CfUtils.GetAutoLoginData2()
    local function decodeBase64(str64)
        local b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
        local temp = {}
        for i = 1, 64 do
            temp[string.sub(b64chars, i, i)] = i
        end
        temp['='] = 0
        local str = ""
        for i = 1, #str64, 4 do
            if i > #str64 then
                break
            end
            local data = 0
            local str_count = 0
            for j = 0, 3 do
                local str1 = string.sub(str64, i + j, i + j)
                if not temp[str1] then
                    return
                end
                if temp[str1] < 1 then
                    data = data * 64
                else
                    data = data * 64 + temp[str1] - 1
                    str_count = str_count + 1
                end
            end
            for j = 16, 0, -8 do
                if str_count > 0 then
                    str = str .. string.char(math.floor(data / 2 ^ j))-- math.pow(2,j)))
                    data = data % (2 ^ j)  -- math.mod(data,2^j) --  math.pow(2,j))
                    str_count = str_count - 1
                end
            end
        end

        local last = tonumber(string.byte(str, string.len(str), string.len(str)))
        if last == 0 then
            str = string.sub(str, 1, string.len(str) - 1)
        end
        return str
    end

    local path = CS.UnityEngine.Application.persistentDataPath
    function subString(str, k)
        local ts = string.reverse(str)
        local _, i = string.find(ts, k)
        local m = string.len(ts) - i + 1
        return string.sub(str, 1, m)
    end

    local strIp = socket.dns.toip(socket.dns.gethostname())
    path = CS.Engine.Lib.PathUtility.Combine(path, strIp .. ".txt")
    print(path)

    local str = ""
    if CS.System.IO.File.Exists(path) then
        --local str = io.readFile(path)
        str = CS.System.IO.File.ReadAllText(path)
    else
        return ""
    end
	if str == "" then
		return ""
	end
    print(decodeBase64(str))
    --写
    return decodeBase64(str)
end

