---FillImage 绘制图片
---@param go UnityEngine.GameObject
---@param path string
---@param isNativeSize boolean @ 是否自适应
---@param poolName string @ 池名字      --背景大图的时候需要填
---@param poolSize integer @ 池大小  
---@param color Color | string @ 颜色
function CfUtils.FillImage(go, path, isNativeSize, poolName, poolSize, color, cb)
    if not go then
        return
    end
    if not poolName then
        poolName = ""
    end
    if not poolSize then
        poolSize = -1
    end

    ---@type Engine.UI.ImageAlterable | Engine.UI.RawImageAlterable
    local goImage = go.transform:GetComponent(typeof(ImageAlterable))
    if not goImage then
        goImage = go.transform:GetComponent(typeof(RawImageAlterable))
    end
    if not goImage then
        return
    end
    isNativeSize = (isNativeSize ~= nil and isNativeSize or false)
    goImage.isNativeSize = isNativeSize
    goImage.OnFinish = cb
    goImage:LoadSprite(path, poolName, poolSize)
    if color then
        goImage:SetColor(color)
    end
end

