---@param go UnityEngine.GameObject
---@param url string
function CfUtils.FillWebImage(go, url)
    if not go or not url then
        return
    end
    local webImg = go.transform:GetComponent(typeof(CS.Engine.UI.WebImage))

    local strs = CfUtils.Split(url, "/")
    local md5 = ""
    if strs then
        local md5Strs = CfUtils.Split(strs[#strs], ".")
        if md5Strs then
            md5 = checkString(md5Strs[1])
        end
    end
    webImg.Url = url
    webImg.Md5 = md5
    webImg.SavePath = ""
    webImg:StartCoroutine(util.cs_generator(function()
        coroutine.yield(Yielders.EndOfFrame)
        webImg:LoadSprite()
    end))
end

---@param go UnityEngine.GameObject
---@param url string
function CfUtils.FillWebRawImage(go, url , isNative)
    if not go or not url then
        return
    end
    local name = "WebRawImage"
    local webImg = go.transform:GetComponent(typeof(CS.Engine.UI.WebRawImage))
    if isNull(webImg) then
        webImg = go.transform:GetComponent(typeof(CS.Engine.UI.WebImage))
        name = "WebImage"
    end
    if isNull(webImg) then
        return
    end

    local strs = CfUtils.Split(url, "/")
    local md5 = ""
    if strs then
        local md5Strs = CfUtils.Split(strs[#strs], ".")
        if md5Strs then
            md5 = checkString(md5Strs[1])
        end
    end
    webImg.Url = url
    webImg.Md5 = md5
    webImg.SavePath = ""
    webImg:StartCoroutine(util.cs_generator(function()
        coroutine.yield(Yielders.EndOfFrame)
        webImg:LoadSprite()
        if isNative then
            if name == "WebImage" or name == "WebRawImage" then
                webImg.SetNativeSize = true
            else     
                webImg:SetNativeSize()
            end
        end
    end))
end

