---填充角色立绘
---@param go     UnityEngine.GameObject
---@param id     integer 卡牌id/皮肤id
---@param origin Vector2 原点
function CfUtils.FillRoleImage(go, id, origin)
    if not go or not id then
        return
    end

    local goodsType = GoodsUtils.GetIdType(id)
    local skinId = nil
    if goodsType == Constants.IDType.CharacterCard then
        local cardConf = CardConfMgr:GetInstance():GetCardByRefId(id)
        skinId = cardConf.defaultSkin
    elseif goodsType == Constants.IDType.CardSkin then
        skinId = id
    else
        return
    end

    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(skinId)
    ---@type CardDrawingPosVo
    local cardDrawingPosVo = CfUtils.GetCfVo(AutoIds.IdSetting109, "CardDrawingPosVo", skinId)
    CfUtils.FillImage(go, skinVo.bigCardDrawing, true)
    local scale = checkNumber(cardDrawingPosVo.scale2) / 100.0
    CfUtils.SetScale(go, Vector3.New(scale, scale, scale))
    if origin then
        go.localPosition = Vector3(origin.x + cardDrawingPosVo.x2, origin.y + cardDrawingPosVo.y2, 0)
    end
end

---@param fromPosGo UnityEngine.Transform | UnityEngine.GameObject
---@param toPosGo UnityEngine.Transform | UnityEngine.GameObject
---@param time number
---@param itemId integer
---@param scale number
---@param idAreaType Constants.IDArea
function CfUtils.ShowGetItemAnimator(fromPosGo, toPosGo, time, itemId, scale, idAreaType)
    if not itemId or not fromPosGo or not toPosGo then
        return
    end
    time = time or 1
    scale = scale or 1
    local uiRootTrans = UIModule.RootCanvas

    local fromPos = CfUtils.UIWorldToScreenPos(fromPosGo, uiRootTrans)
    local toPos = CfUtils.UIWorldToScreenPos(toPosGo, uiRootTrans)

    local itemGo = CfUtils.InitItemGo(uiRootTrans, itemId, nil, scale, idAreaType)
    local goRect = itemGo.transform:GetComponent(typeof(RectTransform)).rect
    fromPos = Vector2(fromPos.x - goRect.width * scale * 0.5, fromPos.y + goRect.height * scale * 0.5)
    toPos = Vector2(toPos.x - goRect.width * scale * 0.5, toPos.y + goRect.height * scale * 0.5)

    if itemGo then
        itemGo.transform:GetComponent(typeof(RectTransform)).anchoredPosition = fromPos
        CfUtils.DoTween(time, function(updateValue)
            itemGo.transform:GetComponent(typeof(RectTransform)).anchoredPosition = Vector2.Lerp(fromPos, toPos, updateValue)
        end, function()
            GameObject.Destroy(itemGo)
        end)
    end
end

