---@param url string
---@return UnityEngine.Texture2D | nil
function CfUtils.GetWWWSprite(url)
    if not url then
        return nil
    end
    local ResourceModule = CS.Engine.Modules.ResourceModule
    local WWWLoader = CS.Engine.Modules.WWWLoader
    local TextureUtility = CS.Engine.Lib.TextureUtility
    local Sprite = CS.UnityEngine.Sprite
    local Path = CS.System.IO.Path
    local Downloader = CS.Engine.Lib.Updater.Downloader
    local Yielders = CS.Engine.Lib.Yielders
    local info = io.pathInfo(url)
    local savePath = Path.Combine(Path.Combine(CS.UnityEngine.Application.persistentDataPath, "External"), info.filename)
    local saveSecond = 36000
    local downLoader = Downloader.Load(url, savePath, saveSecond)
    local urlMd5 = CfUtils.GetUrlMds(url)
    downLoader.Md5 = urlMd5
    downLoader:Start()
    while (not downLoader.IsFinished) do
        coroutine.yield(Yielders.EndOfFrame)
    end
    while (downLoader.IsError) do
        return nil
    end

    local oldMd5 = string.trim(string.lower(KTool.MD5_File(savePath)))
    if oldMd5 ~= urlMd5 then
        return nil
    end

    --[[
    local loadPath = ResourceModule.GetFileProtocol()..savePath
    local wwwLoader = WWWLoader.Load(loadPath)
    while(not wwwLoader.IsCompleted) do
        coroutine.yield(Yielders.EndOfFrame)
    end
    while(not wwwLoader.IsSuccess) do
        return nil
    end
    ]]

    --local texture = TextureUtility.CreateTexture2DFromPngBytes(wwwLoader._www.downloadHandler.data)
    local texture = TextureUtility.LoadTexture(savePath)
    --local spr = Sprite.Create(texture, CS.UnityEngine.Rect(0, 0, texture.width, texture.height), Vector2(0.5, 0.5), 100, 0, CS.UnityEngine.SpriteMeshType.FullRect)
    return texture
end

--获取一个链接的md5
---@param url string
---@return string
function CfUtils.GetUrlMds(url)
    local md5 = ""
    if not url then
        return md5
    end

    local strs = CfUtils.Split(url, "/")
    if strs then
        local md5Strs = CfUtils.Split(strs[#strs], ".")
        if md5Strs then
            md5 = checkString(md5Strs[1])
        end
    end
    return md5
end

