function CfUtils.StrChange(str, maxLen, strChange)
    local utf8 = require("Frame.utf8")

    maxLen = checkNumber(maxLen)
    str = checkString(str)

    if not strChange then
        strChange = "..."
    end
    local length = utf8.len(str)
    if length <= maxLen then
        return str
    end

    str = utf8.sub(str, 1, maxLen + 1)
    str = str .. strChange
    return str
end

