---@param cb fun():void
function CfUtils.StartCoroutineWithBlocker(cb)
    ---@type Engine.UI.UIRaycastBlocker
    local blocker = UIRaycastBlocker.Instance
    blocker:AddCondition("StartCoroutineWithBlocker")
    xTry(function()
        cs_coroutine.start(function()
            cs_coroutine.yield_return(cb())
            blocker:RemoveCondition("StartCoroutineWithBlocker")
        end)
    end, function(msg)
        blocker:RemoveCondition("StartCoroutineWithBlocker")
        printError(msg)
    end)
end


