--- 遍历列表控件 创建的全部共享节点（FIXME 可能没有使用场景了）
--- 指定显示的节点请：使用 GetShownItemByItemIndex 方法
--- 全部显示的节点请：使用 RefreshAllShownItem 方法
---@param listView SuperScrollView.LoopListView2
---@param srcPath string
---@param eachCallback fun(cellEnv:any):boolean @ return 是否继续遍历
function CfUtils.ListViewEachItem(listView, srcPath, eachCallback)
    if isNull(listView) then
        return
    end
    for itemCount = 1, listView.ShownItemCount do
        -- 这个东西实际是创建出的cell数量，所以远超屏幕中显示出来的数量
        local cellNode = listView:GetShownItemByIndex(itemCount - 1)
        if not isNull(cellNode) then
            local nodeEnv = CfUtils.GetLuaScr(cellNode, srcPath)
            if not isNull(nodeEnv) then
                if eachCallback then
                    if eachCallback(nodeEnv,itemCount,listView.ShownItemCount) then
                        break
                    end
                end
            end
        end
    end
end

--- 计算列表控件 显示出来的节点数量
