---@param layerMask integer
---@return string[]
function CfUtils.LayerMaskToNames(layerMask)
    local original = checkInt(layerMask)
    local output = {}
    for i = 1, 32 do
        local abit = i - 1
        local shifted = 1 << abit
        if ((original & shifted) == shifted) then
            local layerName = LayerMask.LayerToName(abit)
            if not string.isEmpty(layerName) then
                table.insert(output, layerName)
            end
        end
    end
    return output
end

---@param layerMask string[]
---@return integer
function CfUtils.LayerMaskByNames(names)
    return LayerMask.GetMask(table.unpack(names))
end

---@param layerMask integer
---@param names string[]
---@return integer
function CfUtils.LayerMaskRemoves(layerMask, names)
    local resultList = {}
    local removeMap  = {}
    for _, name in ipairs(names or {}) do
        removeMap[tostring(name)] = true
    end
    local nameList = CfUtils.LayerMaskToNames(layerMask)
    for _, name in ipairs(nameList) do
        if not removeMap[tostring(name)] then
            table.insert(resultList, name)
        end
    end
    return CfUtils.LayerMaskByNames(resultList)
end

---@param layerMask integer
---@param names string[]
---@return integer
function CfUtils.LayerMaskAppends(layerMask, names)
    local resultMap = {}
    for _, name in ipairs(names or {}) do
        resultMap[tostring(name)] = true
    end
    local nameList = CfUtils.LayerMaskToNames(layerMask)
    for _, name in ipairs(nameList) do
        resultMap[tostring(name)] = true
    end
    return CfUtils.LayerMaskByNames(table.keys(resultMap))
end
