---获取图片完整路径
---@param path string 配表中的缩略路径，因为活动中会出现图片路径通过接口返回的情况，所以这里做一次路径补全
---@param isLang string 是否添加语言索引
---@return string
function CfUtils.GetImageFullPath(path ,isLang)
    if path == nil then return end
    local strs = string.split(path, ":")
    if #strs == 1 then
        return path
    end
    local str2 = strs[2]
    if isLang then
        local langSuffix = GameUtils.GetLangSuffix()
        if not string.isEmpty(langSuffix) then
            str2 = str2 .. langSuffix
        end
    end
    return CS.GameUtils.GetCombineResourceDirPath(checkInt(strs[1]), str2)
end


--- 获取list指定下标的 宽度位置（注意：initListView 时，一定要传入 mItemDefaultWithPaddingSize 参数，才能保证计算准确）
---@param listView SuperScrollView.LoopListView2
---@param cellName string
---@param targetIndex integer @ strar with 0
function CfUtils.CalculateListTargetX(listView, cellName, targetIndex)
    local listItemData   = listView:GetItemPrefabConfData(cellName)
    local listItemWidth  = listItemData.mItemPrefab.transform.sizeDelta.x
    local listItemGapW   = listItemWidth + listItemData.mPadding
    local listContainerW = listView.ItemTotalCount * listItemGapW - listItemData.mPadding
    local listLimitDist  = listContainerW - listView.ViewPortSize
    local targetAnchorX  = math.max(0, math.min(targetIndex * listItemGapW, listLimitDist))
    return -targetAnchorX
end


--- 获取list指定下标的 高度位置（注意：initListView 时，一定要传入 mItemDefaultWithPaddingSize 参数，才能保证计算准确）
---@param listView SuperScrollView.LoopListView2
---@param cellName string
---@param targetIndex integer @ strar with 0
function CfUtils.CalculateListTargetY(listView, cellName, targetIndex)
    local listItemData   = listView:GetItemPrefabConfData(cellName)
    local listItemHeight = listItemData.mItemPrefab.transform.sizeDelta.y
    local listItemGapH   = listItemHeight + listItemData.mPadding
    local listContainerH = listView.ItemTotalCount * listItemHeight - listItemData.mPadding
    local listLimitDist  = listContainerH - listView.ViewPortSize
    local targetAnchorY  = math.max(0, math.min(targetIndex * listItemGapH, listLimitDist))
    return targetAnchorY
end

function CfUtils.GetNight12PMToNowLeaveTime()
    -- 获取当前时间戳
    local now = os.time()
    -- 获取当前日期
    local date = os.date("*t", now)

    -- 设置时间为当天晚上12点
    date.hour = 23
    date.min = 59
    date.sec = 59

    -- 将日期转换为时间戳
    local tonight_12pm = os.time(date)
    -- 计算时间差
    local remainTime = tonight_12pm - now + 1
    return remainTime
end

--- 通过名字全场景下查找 GameObject，无论是否激活状态
---@param objName string
---@return UnityEngine.GameObject | nil
function CfUtils.GameObjectFindInactive(objName)
    if isNull(objName) then return nil end
    local objs = GameObject.FindObjectsOfType(typeof(GameObject), true)
    if isNotNull(objs) then
        for objIndex = 1, objs.Length do
            ---@type UnityEngine.GameObject
            local obj = objs[objIndex - 1]
            if obj.name == objName then
                return obj
            end
        end
    end
    return nil
end


