---获取自定义str长度(单字节记为1, 其余计为2)
function CfUtils.GetCustomStringLen(str)
    local realByteCount = #str
    local curBytePos = 1
    local length = 0
    
    while(true) do
        local step = 1 --遍历字节的递增值
        local customLength = 1
        local byteVal = string.byte(str,curBytePos)
        if byteVal > 239 then
            step = 4
            customLength = 2
        elseif byteVal > 223 then
            step = 3
            customLength = 2
        elseif byteVal > 191 then
            step = 2
            customLength = 2
        else
            step = 1
            customLength = 1
        end
        curBytePos = curBytePos + step
        length = length + customLength

        if curBytePos > realByteCount then
            break
        end
    end
    
    return length
end

------------------------------------------------- [events]
do
    --- 封装 事件定义装饰器
    ---@param eventMap table<string, function>
    ---@return table<string, function>
    function CfUtils.EventsDecorated(eventMap)
        local decoratorMap = {}
        for eventName, eventCallback in pairs(eventMap or {}) do
            decoratorMap[eventName] = Events.AddListener(eventName, eventCallback)
        end
        return decoratorMap
    end

    
    --- 注销 事件定义装饰器
    ---@param decoratorMap table<string, function>
    function CfUtils.EventsUndecorated(decoratorMap)
        for eventName, eventCallback in pairs(decoratorMap or {}) do
            Events.RemoveListener(eventName, eventCallback)
            decoratorMap[eventName] = nil
        end
    end
end


------------------------------------------------- [gui]
do
    --- loopList控件 状态保存
    ---@param loopListGo SuperScrollView.LoopListView2
    ---@return table
    function CfUtils.GuiLoopListStateSave(loopListGo)
        local stateData = {}
        if isNull(loopListGo) then return stateData end

        -- 当前显示出来的最小item索引
        local minShowItemIndex = 0
        for itemCount = 1, loopListGo.ShownItemCount do
            local cellNode = loopListGo:GetShownItemByIndex(itemCount - 1)
            if minShowItemIndex == 0 then
                minShowItemIndex = cellNode.ItemIndex
            else
                minShowItemIndex = math.min(minShowItemIndex, cellNode.ItemIndex)
            end
        end

        -- 是否垂直模式
        if loopListGo.IsVertList then
            -- 滚动容器：记录当前位置
            local moveIdx  = minShowItemIndex + 1
            local currentY = loopListGo.ContainerTrans.anchoredPosition.y

            -- 滚动容器：滚动至索引的0偏移的位置
            loopListGo:MovePanelToItemIndex(moveIdx, 0)

            -- 同样索引位置下，算出 0偏移的位置 和 当前位置 的滚动距离差值
            local originY = loopListGo.ContainerTrans.anchoredPosition.y
            local offsetY = originY - currentY

            -- 滚动容器：位置还原回去
            loopListGo:MovePanelToItemIndex(moveIdx, offsetY)

            -- 记录状态数据
            stateData.moveIdx = moveIdx
            stateData.offsetY = offsetY

        else
            -- 滚动容器：记录当前位置
            local moveIdx  = minShowItemIndex + 1
            local currentX = loopListGo.ContainerTrans.anchoredPosition.x

            -- 滚动容器：滚动至索引的0偏移的位置
            loopListGo:MovePanelToItemIndex(moveIdx, 0)

            -- 同样索引位置下，算出 0偏移的位置 和 当前位置 的滚动距离差值
            local originX = loopListGo.ContainerTrans.anchoredPosition.x
            local offsetX = originX - currentX

            -- 滚动容器：位置还原回去
            loopListGo:MovePanelToItemIndex(moveIdx, offsetX)

            -- 记录状态数据
            stateData.moveIdx = moveIdx
            stateData.offsetX = offsetX
        end
        return stateData
    end


    --- loopList控件 状态加载
    ---@param loopListGo SuperScrollView.LoopListView2
    ---@param stateData table
    function CfUtils.GuiLoopListStateLoad(loopListGo, stateData)
        local stateData = checkTable(stateData)
        if isNull(loopListGo) then return stateData end

        -- 是否垂直模式
        if loopListGo.IsVertList then
            local moveIdx = checkInt(stateData.moveIdx)
            local offsetY = checkInt(stateData.offsetY)
            loopListGo:MovePanelToItemIndex(moveIdx, offsetY)
        else
            local moveIdx = checkInt(stateData.moveIdx)
            local offsetX = checkInt(stateData.offsetX)
            loopListGo:MovePanelToItemIndex(moveIdx, offsetX)
        end
    end
end
-- 获取语言配置
function CfUtils.GetConfigLang()
    local SDKService = import('Game.Entry.SDKService')
    ---@type SDKService
    local SDKService = SDKService:GetInstance()
    local AppEngine = CS.Engine.Lib.AppEngine
    local languages =  AppEngine.GetConfig("Engine.I18N", "Languages")
    print("[设置] 支持语言", languages)
    languages = string.split(languages, ',')
    if SDKService:isIndo() then
        languages = {"en_UK"}
    elseif (SDKService:IsCN() or SDKService:IsDuoLe()) and checkInt(IS_REVIEW_INT) <= 1 then
        languages = {"zh_CN"}
    end
  
    return languages
end

function CfUtils.isTH()
    local languages =  AppEngine.GetConfig("Engine.I18N", "Languages")
    if string.contains(languages, "th_TH") and (not KTool.IsMobile()) then
        return true
    end
    return false
end

