function CfUtils.OpenURL(url)
    local DeviceID = CS.Engine.Http.DeviceID 
    local staticType =typeof(CS.Engine.Http.DeviceID)
    local BindingFlags = CS.System.Reflection.BindingFlags
    local isHaveStaticMethod = isNotNull(staticType:GetMethod('OpenURL' , BindingFlags.Static | BindingFlags.Public)) 
    if isHaveStaticMethod then
        DeviceID.OpenURL(url)
    else 
        CS.UnityEngine.Application.OpenURL(url)
    end
end

